module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    // Internal register to store the previous value of 'in'
    logic [31:0] prev_in;

    // Combinational logic to detect falling edges (1 -> 0 transition)
    // A falling edge occurs when the current input is 0 AND the previous input was 1
    logic [31:0] falling_edge_detect;
    assign falling_edge_detect = ~in & prev_in;

    // Sequential logic: Update prev_in on every positive clock edge
    // If reset is active high, clear prev_in to 0
    always_ff @(posedge clk) begin
        if (reset) begin
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
        end
    end

    // Sequential logic: Update out on every positive clock edge
    // If reset is active high, clear out to 0
    // Otherwise, set the corresponding bit in out if a falling edge is detected
    always_ff @(posedge clk) begin
        if (reset) begin
            out <= 32'b0;
        end else begin
            out <= out | falling_edge_detect;
        end
    end

endmodule

