    input  mode,
    input  too_cold,
    input  too_hot,
    input  fan_on,
    output heater,
    output aircon,
    output fan
);

    // Internal signals to store the state of the heater and air conditioner
    reg    heater_reg;
    reg    aircon_reg;

    // Fan logic: On if either the heater/aircon is on, or the user explicitly requests it
    assign fan = heater_reg | aircon_reg | fan_on;

    always @(*) begin
        // Default assignments to prevent latches
        heater_reg  = 1'b0;
        aircon_reg  = 1'b0;

        if (mode == 1'b1) begin
            // ------- HEATING MODE -------
            // Turn on heater if too cold
