        else begin
            // ------- COOLING MODE -------
            // Turn on air conditioner if too hot
            if (too_hot == 1'b1)
                aircon_reg = 1'b1;
            // Heater stays off
        end
    end

    // Assign outputs from the internal registers
    assign heater = heater_reg;
    assign aircon = aircon_reg;

endmodule

