    // y[5:0] = 6'b000001 -> A
    // y[5:0] = 6'b000010 -> B
    // y[5:0] = 6'b000100 -> C
    // y[5:0] = 6'b001000 -> D
    // y[5:0] = 6'b010000 -> E
    // y[5:0] = 6'b100000 -> F

    // Next-state logic derived by inspection of the FSM:
    //   A(0) --1--> B,  A(0) --0--> A
    //   B(0) --1--> C,  B(0) --0--> D
    //   C(0) --1--> E,  C(0) --0--> D
    //   D(0) --1--> F,  D(0) --0--> A
    //   E(1) --1--> E,  E(1) --0--> D
    //   F(1) --1--> C,  F(1) --0--> D

    // Y1  = next state of y[1]
    // Y3  = next state of y[3]

    // From the state transition table and one-hot encoding:
    //   A: y=000001 -> y[1]=0, y[3]=0
    //   B: y=000010 -> y[1]=1, y[3]=0
    //   C: y=000100 -> y[1]=0, y[3]=0
    //   D: y=001000 -> y[1]=0, y[3]=1
    //   E: y=010000 -> y[1]=0, y[3]=0
    //   F: y=100000 -> y[1]=0, y[3]=0

    // Next-state equations (one-hot excitation):
    //   Y1 is asserted (next state has y[1]=1) only when transitioning to state B.
    //   The only transition to B is A(0) --1--> B, i.e. current state A and w=1.
    //   Current state A is identified by y[5]==1 and all other bits 0.
    assign Y1 = y[5] & ~y[4] & ~y[3] & ~y[2] & ~y[1] & ~y[0] & ~w;

