    //   • B: y[4]==1, all other bits 0
    //   • C: y[3]==1, all other bits 0
    //   • F: y[5]==1, all other bits 0
    // In all cases the input w must be 0.
    assign Y3 = (y[4] & ~y[3] & ~y[2] & ~y[1] & ~y[0] & ~w) |
                (y[3] & ~y[4] & ~y[2] & ~y[1] & ~y[0] & ~w) |
                (y[5] & ~y[4] & ~y[3] & ~y[2] & ~y[1] & ~y[0] & ~w);

endmodule

