module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // State encoding: 2 bits
    // 2'b00: IDLE (waiting for reset release)
    // 2'b01: COLLECTING (shifting bits in)
    // 2'b10: DONE (output valid, waiting for next reset)
    // 2'b11: UNUSED
    reg [1:0] state;
    reg [1:0] next_state;

    // Shift register to accumulate the input number (LSB first)
    reg [31:0] shift_reg;
    reg [31:0] next_shift;

    // Counter for the number of bits processed
    reg [5:0] bit_count;
    reg [5:0] next_count;

    // Output assignment: Z is the MSB of the complemented shift register
    // When in DONE state, z = ~shift_reg[31];
    // In other states, z is don't-care (driven to 0 for simulation)
    assign z = (state == 2'b10) ? ~shift_reg[31] : 1'b0;

    // State register update on positive edge of clk
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= 2'b00;
            shift_reg   <= 32'd0;
            bit_count   <= 6'd0;
        end else begin
            state       <= next_state;
            shift_reg   <= next_shift;
            bit_count   <= next_count;
        end
    end

    // Next-state and output logic (combinational)
    always @(*) begin
        // Default assignments (hold current values)
        next_state     = state;
        next_shift     = shift_reg;
        next_count     = bit_count;

        case (state)
            2'b00: // IDLE state
                begin
                    // Wait for reset release (active-low effective here,
                    // but areset is asynchronous high reset, so we wait
                    // until areset is de-asserted in simulation flow,
                    // though the FF handles it. Here we just transition
                    // on the first clock after reset release.)
                    // The specification says: "conversion begins when Reset is released"
                    // We transition to COLLECTING on the next positive edge if areset=0.
                    // Since the FF handles the reset, we just stay in IDLE
                    // until the FF updates. To model the "begin when released"
                    // behavior, we can transition here based on areset,
                    // but typically the FF edge handles it.
                    // For this implementation, we assume the FF transition
                    // out of IDLE happens when areset is 0 at the posedge.
                    // We explicitly transition now for clarity:
                    if (!areset) begin
                        next_state = 2'b01; // COLLECTING
                        next_count = 6'd0;
                        next_shift = 32'd0;
                    end
                end

            2'b01: // COLLECTING state
                begin
                    // Shift in the new LSB (x)
                    next_shift = {x, shift_reg[31:1]};
                    next_count = bit_count + 1;

                    // If we have processed 32 bits (arbitrary limit for
                    // register width), go to DONE. Otherwise stay collecting.
                    // "arbitrary length" is handled by the shift register width;
                    // we cap at 32 bits here for practical synthesis.
                    if (bit_count == 6'd31) begin
                        next_state = 2'b10; // DONE
                    end else begin
                        next_state = 2'b01; // COLLECTING
                    end
                end

            2'b10: // DONE state
                begin
                    // Hold state until reset is asserted.
                    // "stops when Reset is asserted"
                    if (areset) begin
                        next_state = 2'b00; // IDLE
                    end else begin
                        next_state = 2'b10; // DONE
                    end
                end

            default: next_state = 2'b00;
        endcase
    end

endmodule

