module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);

    // State encoding: 0 = search, 1 = byte 1 received, 2 = byte 2 received, 3 = byte 3 received
    typedef enum reg [1:0] {
        S_IDLE    = 2'b00,
        S_BYTE1   = 2'b01,
        S_BYTE2   = 2'b10,
        S_BYTE3   = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous, active high reset)
    always @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state and output logic (combinational)
