    reg [511:0] q_reg;

    // Combinational logic to compute next state
    wire [511:0] q_next;

    // Generate the next state for each cell
    // Boundaries are implicitly zero: q[-1] = 0, q[512] = 0
    genvar i;
    generate
        for (i = 0; i < 512; i = i + 1) begin : cell_update
            // Left neighbour: q_reg[i-1] if i>0 else 0
            // Right neighbour: q_reg[i+1] if i<511 else 0
