            assign left  = (i == 0) ? 1'b0 : q_reg[i-1];
            assign center = q_reg[i];
            assign right = (i == 511) ? 1'b0 : q_reg[i+1];

            // Rule 110 lookup
            // Pattern (left, center, right) -> next state
            // 111 -> 0
            // 110 -> 1
            // 101 -> 1
            // 100 -> 0
            // 011 -> 1
            // 010 -> 1
            // 001 -> 1
            // 000 -> 0
