                               (left & center & ~right) |
                               (left & ~center & right) |
                               (~left & center & right) |
                               (~left & center & ~right) |
                               (~left & ~center & right);
        end
    endgenerate

    // Synchronous update
    always @(posedge clk) begin
        if (load)
            q_reg <= data;
        else
            q_reg <= q_next;
