module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic done_counting,
    input  logic ack,
    output logic shift_ena,
    output logic counting,
    output logic done
);

// State type declaration
typedef enum logic [2:0] {
    S_IDLE    = 3'b000,
    S_SHIFT1  = 3'b001,
    S_SHIFT2  = 3'b010,
    S_SHIFT3  = 3'b011,
    S_SHIFT4  = 3'b100,
    S_COUNT   = 3'b101,
    S_DONE    = 3'b110
} state_t;

state_t state, next_state;

// Shift register for pattern detection (1101)
logic [3:0] shift_reg;

// State register and next-state logic
always_ff @(posedge clk) begin
    if (reset) begin
        state <= S_IDLE;
        shift_reg <= 4'b0000;
    end else begin
        // Shift in the serial data
        shift_reg <= {shift_reg[2:0], data};

        // Default next state is current state
        next_state <= state;

        case (state)
            S_IDLE: begin
                // Check for the start pattern 1101
                if (shift_reg == 4'b1101) begin
                    next_state <= S_SHIFT1;
                end
            end

            S_SHIFT1: begin
                next_state <= S_SHIFT2;
            end

            S_SHIFT2: begin
                next_state <= S_SHIFT3;
            end

            S_SHIFT3: begin
                next_state <= S_SHIFT4;
            end

            S_SHIFT4: begin
                // After 4 shifts, move to counting state
                next_state <= S_COUNT;
            end

            S_COUNT: begin
                // Wait for done_counting to be asserted
                if (done_counting) begin
                    next_state <= S_DONE;
                end
            end

            S_DONE: begin
                // Wait for user acknowledgment
                if (ack) begin
                    next_state <= S_IDLE;
                end
            end

            default: begin
                next_state <= S_IDLE;
            end
        endcase
    end
end

// Output logic (combinational)
assign shift_ena = (state >= S_SHIFT1 && state <= S_SHIFT4) ? 1'b1 : 1'b0;
assign counting  = (state == S_COUNT)     ? 1'b1 : 1'b0;
assign done      = (state == S_DONE)      ? 1'b1 : 1'b0;

endmodule

