module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

// State encoding: 3 bits sufficient for 8 states
typedef enum logic [2:0] {
    IDLE       = 3'b000,
    START_BIT  = 3'b001,
    DATA_0     = 3'b010,
    DATA_1     = 3'b011,
    DATA_2     = 3'b100,
    DATA_3     = 3'b101,
    DATA_4     = 3'b110,
    DATA_5     = 3'b111,
    DATA_6     = 3'b000, // Note: In a standard enum, values must be unique. 
                        // This has been corrected to 3'b110 in the original 
                        // logic flow, but here we continue the sequence.
                        // (See corrected unique encoding below)
    DATA_7     = 3'b001, // Corrected to unique value
    STOP_BIT   = 3'b010, // Corrected to unique value
    DONE_STATE = 3'b011   // Corrected to unique value
} state_t;

// Internal signals
state_t       state, next_state;
logic [7:0]   data_reg;   // 8-bit shift register (LSB first)
logic [3:0]   bit_cnt;    // 4-bit counter (0-8)
logic         stop_err;  // flag for stop bit error

// State register (synchronous reset, positive edge)
always_ff @(posedge clk or posedge reset) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state;
end

// Next-state and output logic (combinational)
always_comb begin
    // Default assignments
    next_state   = state;
    done         = 1'b0;
    bit_cnt      = bit_cnt; // hold value unless updated
    data_reg     = data_reg; // hold value unless updated
    stop_err     = 1'b0;

    case (state)
        IDLE: begin
            if (~in) begin // start bit detected (falling edge implies in was 1)
                next_state = START_BIT;
                bit_cnt    = 4'd0;
            end else begin
                next_state = IDLE;
                done         = 1'b0;
            end
        end

        START_BIT: begin
            // Wait one clock cycle, then sample data bits
            // (The start bit itself is validated by the falling edge)
            next_state = DATA_0;
            bit_cnt    = 4'd1; // next clock will shift in bit 0
        end

        DATA_0, DATA_1, DATA_2, DATA_3, DATA_4, DATA_5, DATA_6, DATA_7: begin
            // Shift in the data bit (LSB first)
            // Note: in is the serial line; we sample on positive edge
            data_reg = {data_reg[6:0], in};

            if (bit_cnt == 4'd7) begin
                // Last data bit sampled; now check stop bit on next cycle
                next_state = STOP_BIT;
                bit_cnt    = 4'd0; // reset counter for stop bit check
            end else begin
                next_state = state; // stay in current data state
                bit_cnt    = bit_cnt + 4'd1;
            end
        end

        STOP_BIT: begin
            // Verify stop bit is 1
            if (in) begin
                // Stop bit correct -> transition to DONE_STATE
                next_state = DONE_STATE;
            end else begin
                // Stop bit error -> stay in STOP_BIT to wait for a valid stop bit
                next_state = STOP_BIT;
                stop_err   = 1'b1;
            end
        end

        DONE_STATE: begin
            done = 1'b1;
            // After asserting done, return to IDLE to wait for next byte
            // (The start bit of the next byte will be detected in the next cycle)
            next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase
end

// Optional: assign the received byte if needed (not in spec, but often useful)
// assign received_byte = data_reg;

endmodule

