module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal register holding the current generation
    reg [255:0] state;

    // Helper function to count neighbours with toroidal wrapping
    function automatic [3:0] count_neighbours;
        input [255:0] s;
        integer r, c, nr, nc, sum, r_off, c_off;
        begin
            sum = 0;
            for (r = 0; r < 16; r = r + 1) begin
                for (c = 0; c < 16; c = c + 1) begin
                    // Accumulate neighbours of cell (r,c)
                    for (r_off = -1; r_off <= 1; r_off = r_off + 1) begin
                        for (c_off = -1; c_off <= 1; c_off = c_off + 1) begin
                            if (r_off == 0 && c_off == 0) continue;
                            // Wrap-around indices
                            nr = (r + r_off + 16) % 16;
                            nc = (c + c_off + 16) % 16;
                            // Flattened index: row * 16 + col
                            sum = sum + s[nr * 16 + nc];
                        end
                    end
                end
            end
            count_neighbours = sum[3:0]; // at most 8, fits in 4 bits
        end
    endfunction

    always @(posedge clk) begin
        if (load) begin
            // Load the initial state synchronously
            state <= data;
        end else begin
            // Compute next generation
            integer r, c;
            reg [3:0] n;

            // Iterate through every cell in the 16x16 grid
            for (r = 0; r < 16; r = r + 1) begin
                for (c = 0; c < 16; c = c + 1) begin
                    // Get neighbour count for current cell
                    n = count_neighbours(state);

                    // The function counts for ALL cells. We need the count 
                    // for the specific (r,c). Since the function iterates all, 
                    // we must extract the specific value. 
                    // However, the function as written returns the SUM of ALL 
                    // neighbours for ALL cells. We need to refactor to get one 
                    // cell's count. 

                    // Correct approach: Calculate neighbour for (r,c) specifically.
                    // We re-declare local variables or use the function logic inline 
                    // for just this cell, or adjust the function to take r,c.
                    // Given the constraint of not changing ports, I will inline 
                    // the counting logic for the specific cell here to ensure 
                    // synthesisability and correctness regarding the index.

                    // Local count for this specific cell
                    integer r_off, c_off;
                    reg [3:0] local_n;
                    local_n = 4'b0;

                    for (r_off = -1; r_off <= 1; r_off = r_off + 1) begin
                        for (c_off = -1; c_off <= 1; c_off = c_off + 1) begin
                            if (r_off == 0 && c_off == 0) continue;
                            nr = (r + r_off + 16) % 16;
                            nc = (c + c_off + 16) % 16;
                            local_n = local_n + s[nr * 16 + nc];
                        end
                    end

                    // Apply rules
                    if (local_n == 3)
                        state[r*16 + c] <= 1'b1;
                    else if (local_n == 2)
                        state[r*16 + c] <= state[r*16 + c]; // keep current
                    else
                        state[r*16 + c] <= 1'b0;
                end
            end
        end
    end

    // Assign output q to the internal state (continuously driven)
    assign q = state;

endmodule

