module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

    // State encoding: IDLE, START, DATA, STOP
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;
    reg [1:0] state, next_state;
    reg [2:0] bit_count;  // Counter for data bits (0 to 7)

    // State register update (positive edge triggered, synchronous reset)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            done  <= 1'b0;
            out_byte <= 8'b0;
            bit_count <= 3'b0;
        end else begin
            state <= next_state;

            // Default assignments to prevent latches
            done <= 1'b0;

            case (state)
                IDLE: begin
                    if (~in) begin  // Start bit detected (falling edge assumed as 0)
                        next_state <= START;
                        bit_count <= 3'b0;
                        out_byte <= 8'b0;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                START: begin
                    // Wait for one clock cycle (or sample in real hardware)
                    // Here we just transition to DATA on the next state transition condition
                    // In a synchronous design, we usually sample after a delay.
                    // For this FSM, we assume the start bit is valid for one cycle 
                    // or we use a counter. Here we simply move to DATA.
                    next_state <= DATA;
                end

                DATA: begin
                    // Shift the input bit into out_byte (LSB first)
                    // Note: 'in' is the serial data line
                    out_byte <= {in, out_byte[7:1]};

                    if (bit_count == 3'd7) begin
                        // All 8 data bits received, move to STOP
                        next_state <= STOP;
                        bit_count <= 3'b0; // Reset bit counter for next byte
                    end else begin
                        bit_count <= bit_count + 1'b1;
                        next_state <= DATA;
                    end
                end

                STOP: begin
                    // Verify stop bit is 1
                    if (in) begin
                        // Stop bit correct, assert 'done' and output valid byte
                        done <= 1'b1;
                        next_state <= IDLE;
                    end else begin
                        // Stop bit incorrect, stay in STOP state 
                        // waiting for a valid stop bit (which is 1)
                        // If in is 0, it might be a start bit of next frame, 
                        // but spec says: "wait until it finds a stop bit before attempting to receive the next byte"
                        // If we see 0 here, it's not a stop bit (which must be 1).
                        // We should probably stay here or go to IDLE if we want to be robust, 
                        // but strict spec: "wait until it finds a stop bit".
                        // If we are in STOP and see 0, we haven't found a stop bit.
                        // Let's stay in STOP until in becomes 1.
                        next_state <= STOP;
                    end
                end
            endcase
        end
    end

endmodule
